// State seals for the county selector: shown when a county in another state is chosen.
// Generated from Wikimedia Commons (Category:SVG state seals of the United States),
// rendered by Wikimedia as PNGs, resized to 256 pixels. Credits and licenses: SEALS.md, and
// "About this software" on the page. Many are insignia whose use states restrict by law.

export interface StateSeal {
  file: string;
  source: string;
  author: string;
  license: string;
  licenseUrl: string;
  insignia: boolean;
  /** PNG, base64. */
  png: string;
}

